$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$mdPath=(Get-ChildItem 'E:\Projects_MT5\XYN_Trader\outputs' -Filter '*.md' | Select-Object -First 1).FullName
$outPath='E:\Projects_MT5\XYN_Trader\outputs\XYN_Trader_User_Guide.docx'
$tmp=Join-Path $env:TEMP ('xyn_docx_'+[guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path (Join-Path $tmp 'word\_rels'),(Join-Path $tmp '_rels'),(Join-Path $tmp 'docProps') -Force|Out-Null
function X([string]$s){[System.Security.SecurityElement]::Escape($s)}
function Run([string]$s,[bool]$bold=$false,[string]$font='Aptos',[string]$color='000000'){$b=if($bold){'<w:b/>'}else{''};'<w:r><w:rPr><w:rFonts w:ascii="'+$font+'" w:hAnsi="'+$font+'" w:eastAsia="'+$font+'"/><w:color w:val="'+$color+'"/>'+$b+'</w:rPr><w:t xml:space="preserve">'+(X $s)+'</w:t></w:r>'}
function Inline([string]$s){$s=$s-replace '\[([^\]]+)\]\([^\)]+\)','$1';$o='';foreach($p in [regex]::Split($s,'(\*\*[^*]+\*\*|`[^`]+`)')){if(!$p){continue};if($p.StartsWith('**')){$o+=Run $p.Substring(2,$p.Length-4) $true}elseif($p.StartsWith('`')){$o+=Run $p.Substring(1,$p.Length-2) $false 'Consolas' '333333'}else{$o+=Run $p}};$o}
function Para([string]$inner,[string]$style='Normal',[string]$align='left'){ '<w:p><w:pPr><w:pStyle w:val="'+$style+'"/><w:jc w:val="'+$align+'"/></w:pPr>'+$inner+'</w:p>' }
function Cell([string]$txt,[bool]$header=$false){$fill=if($header){'365A27'}else{'F1F5EC'};$col=if($header){'FFFFFF'}else{'000000'};'<w:tc><w:tcPr><w:shd w:fill="'+$fill+'"/><w:tcW w:w="2400" w:type="dxa"/></w:tcPr>'+ (Para (Run $txt $header 'Aptos' $col))+'</w:tc>'}
$lines=Get-Content -LiteralPath $mdPath -Encoding UTF8;$body='';$i=0;$inCode=$false;$code=@()
while($i -lt $lines.Count){$line=$lines[$i];if($line.StartsWith('```')){if(!$inCode){$inCode=$true;$code=@()}else{$inCode=$false;$body+=Para (Run ($code -join "`n") $false 'Consolas' '333333')};$i++;continue};if($inCode){$code+=$line;$i++;continue};if([string]::IsNullOrWhiteSpace($line)){$i++;continue};if($line -eq '---'){$body+='<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="8" w:color="B6E36B"/></w:pBdr></w:pPr></w:p>';$i++;continue};if($line -match '^(#{1,3})\s+(.*)$'){$n=$Matches[1].Length;$t=$Matches[2]-replace '\*\*','';$style=if($n-eq 1){'Title'}elseif($n-eq 2){'Heading1'}else{'Heading2'};$align=if($n-eq 1){'center'}else{'left'};$body+=Para (Inline $t) $style $align;$i++;continue};if($line.StartsWith('|')-and($i+1-lt$lines.Count)-and$lines[$i+1].StartsWith('|')){$rows=@();while($i-lt$lines.Count-and$lines[$i].StartsWith('|')){$r=$lines[$i];if($r-notmatch '^\|\s*[-:| ]+\|\s*$'){$rows+=,@($r.Trim('|').Split('|')|ForEach-Object{$_.Trim()})};$i++};$body+='<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single" w:sz="4" w:color="D0D8C8"/><w:left w:val="single" w:sz="4" w:color="D0D8C8"/><w:bottom w:val="single" w:sz="4" w:color="D0D8C8"/><w:right w:val="single" w:sz="4" w:color="D0D8C8"/><w:insideH w:val="single" w:sz="4" w:color="D0D8C8"/><w:insideV w:val="single" w:sz="4" w:color="D0D8C8"/></w:tblBorders></w:tblPr>';for($ri=0;$ri-lt$rows.Count;$ri++){$body+='<w:tr>';foreach($v in $rows[$ri]){$body+=Cell $v ($ri-eq 0)};$body+='</w:tr>'};$body+='</w:tbl>';continue};if($line-match '^\s*[-*]\s+(.*)$'){$body+=Para (Inline $Matches[1]) 'ListBullet';$i++;continue};if($line-match '^\s*\d+\.\s+(.*)$'){$body+=Para (Inline $Matches[1]) 'ListNumber';$i++;continue};$body+=Para (Inline $line);$i++}
$document='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>BODY_PLACEHOLDER<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="900" w:right="1000" w:bottom="900" w:left="1000"/></w:sectPr></w:body></w:document>' -replace 'BODY_PLACEHOLDER',$body
$styles='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos" w:eastAsia="Aptos"/><w:sz w:val="20"/></w:rPr></w:rPrDefault></w:docDefaults><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:b/><w:color w:val="25351F"/><w:sz w:val="48"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="Heading 1"/><w:rPr><w:b/><w:color w:val="365A27"/><w:sz w:val="34"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="Heading 2"/><w:rPr><w:b/><w:color w:val="4E7D35"/><w:sz w:val="28"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="ListBullet"><w:name w:val="List Bullet"/></w:style><w:style w:type="paragraph" w:styleId="ListNumber"><w:name w:val="List Number"/></w:style></w:styles>'
$ct='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>'
$rels='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>'
$wrels='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'
$core='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>XYN Trader User Guide</dc:title><dc:creator>XYN Trader</dc:creator></cp:coreProperties>'
function W([string]$p,[string]$v){[IO.File]::WriteAllText($p,$v,(New-Object Text.UTF8Encoding($false)))}
W (Join-Path $tmp '[Content_Types].xml') $ct;W (Join-Path $tmp '_rels\.rels') $rels;W (Join-Path $tmp 'word\document.xml') $document;W (Join-Path $tmp 'word\styles.xml') $styles;W (Join-Path $tmp 'word\_rels\document.xml.rels') $wrels;W (Join-Path $tmp 'docProps\core.xml') $core
if(Test-Path $outPath){Remove-Item $outPath -Force};[IO.Compression.ZipFile]::CreateFromDirectory($tmp,$outPath);Remove-Item $tmp -Recurse -Force;Get-Item $outPath|Select-Object FullName,Length
